WFJ.Data.add("book", {
  ["8b0d0a7599348e6c"] = { "試験の結果を待つ間、私はKeganと話して時を過ごした。血石について知っていることを絶えず問いただしたが、彼はペンダントを私にくれた日に語った以上のことは決して話さなかった。また、彼が「Forsaken」と呼ぶ集団――それが彼のアンデッドの一族の名である――の中にいた頃のことも、あまり話さなかった。", "." },
  ["8b5a35e98333f326"] = { "平原でレースをするロケットカーは高度に調整されており、徹底した整備が欠かせません。ですから、ピットクルーが常に現場に待機しているのも不思議ではありません。\n\nクルーたちは絶えず車をテストし、必要に応じて修理や改造を行っています。それが車を最高の状態に保つ唯一の方法なのです。\n\nそこで……我々は、どこかのピットクルーの注意を怠らせる手段を探しています。そうした怠りが生じれば、そのクルーの車はたちまち整備不良に陥るからです。", "." },
  ["8b5b8840ef729bfb"] = { "<HTML>\n<BODY>\n<H1 align=\"center\">\nWESTERN PYLON 配置図\n</H1>\n<BR/>\n<IMG src=\"Interface\\Pictures\\11482_crystals_west\"/>\n</BODY>\n</HTML>", "." },
  ["8b725e067ddfef56"] = { "我々にとって危険なことに、卑しいオークどもは陛下の善良な民を滅ぼすことにより執心しているようです。この二週間のうちに、Blackrock ClanはLakeshireに容赦ない攻勢をかけました。あの暗い日、多くの勇敢な男たちが命を落としました。オークの軍勢があまりの速さと激しさで進撃したため、Everstillに架かる橋は崩れ落ちました。我々の軍需品は大きく減っております。倒れた者の傷を手当てする包帯すら足りません。", "." },
  ["8bbac489f91466fc"] = { "Solenor the Slayer：\n\nSilithusの乾ききった地に、悪鬼Solenor the Slayerが潜んでいる。変装しているのは間違いなく、危険であることも確かだ。近づいて、正体を現させよ。", "." },
  ["8bbf7ecb624d0977"] = { "Scarshieldの野営地でroughshod pikeを見つけよ。奴らはよく、Spirestoneのogreの領域の入り口近くで、寝床の敷物のそばにそれを積み重ねている。\n\npikeを手に入れたら、Highlord Omokkのもとへ突き進め。奴を殺し、その首をpikeに刺すのだ。\n\nそうすれば、真の挑戦への準備が整う。", "." },
  ["8bed19e081e0618f"] = { "奴らはあらゆる方向から襲ってきた。足元の隠れた穴から爪を立てて這い出し、頭上の音もない止まり木から我々の上へ飛び降りてきた。最初の恐慌の数分間で仲間の半数が倒れた。私を含む残りの者は逃げようとした。走りながら、私は多くの兄弟たちが牙と爪に捕らえられるのを見、多くの悲鳴が途切れ、あるいはごぼごぼと音を立てて静まるのを聞いた。\n\n私の知る限り、あの場所から逃げおおせた人間は私だけだ。", "." },
})
